use super::*;
pub fn estimate(text: &str, chars_per_token: u64) -> Result<u64, Error> {
    if chars_per_token == 0 {
        return Err(Error::Invalid("ratio must be positive".into()));
    }
    let n = text.chars().count() as u64;
    Ok(n / chars_per_token + u64::from(n % chars_per_token != 0))
}

use super::*;
pub fn parse_usage(line: &str) -> Result<Usage, Error> {
    let p: Vec<&str> = line.trim().split(',').collect();
    if p.len() != 3 {
        return Err(Error::Invalid("input,output,cached required".into()));
    }
    let mut n = Vec::new();
    for part in p {
        if part.is_empty() || !part.bytes().all(|b| b.is_ascii_digit()) {
            return Err(Error::Invalid("unsigned counter required".into()));
        }
        n.push(part.parse::<u64>().map_err(|_| Error::Limit)?);
    }
    if n[2] > n[0] {
        return Err(Error::Invalid("cached exceeds input".into()));
    }
    Ok(Usage {
        input: n[0],
        output: n[1],
        cached: n[2],
    })
}

use super::*;
pub fn cost(usage: &Usage, rates: &Rates) -> Result<u64, Error> {
    if usage.cached > usage.input {
        return Err(Error::Invalid("cached exceeds input".into()));
    }
    let a = (usage.input - usage.cached)
        .checked_mul(rates.input)
        .ok_or(Error::Limit)?;
    let b = usage.cached.checked_mul(rates.cached).ok_or(Error::Limit)?;
    let c = usage.output.checked_mul(rates.output).ok_or(Error::Limit)?;
    a.checked_add(b)
        .and_then(|x| x.checked_add(c))
        .ok_or(Error::Limit)
}

use super::*;
pub fn reserve(spent: &mut u64, quote: u64, limit: u64) -> Result<u64, Error> {
    let next = spent.checked_add(quote).ok_or(Error::Limit)?;
    if next > limit {
        return Err(Error::Limit);
    }
    *spent = next;
    Ok(limit - next)
}

